const p = await tools.update_plan({plan:[
  {step:"Map repository structure and locate server, data, and integration symbols",status:"in_progress"},
  {step:"Trace each question’s declarations, callers, dispatch, and absence/reality checks",status:"pending"},
  {step:"Recheck line references and compile concise numbered answers",status:"pending"}
]});
text(p);

const qs = [
  ["startup/jobs", "RunOnce|runOnce|Refresh|attachment.*URL|external"],
  ["webhooks", "webhook|Webhook|delivery|SSRF|private|internal"],
  ["idp", "type Provider|Provider interface|oidc|OIDC|oauth2"],
  ["mysql", "NewStore|mysql.New|mysqlStore|INSERT INTO memo"],
  ["reactions", "reaction|Reaction"],
  ["markdown", "Markdown|markdown"],
  ["visibility", "Visibility|visibility|CanView|Visibility"],
  ["redis/rate/cron/graphql", "redis|Redis|rate.limit|RateLimit|cron|Cron|GraphQL|graphql|Rabbit|NATS|nats"]
];
const out = await Promise.all(qs.map(async ([label,pat]) => {
  const r = await tools.exec_command({cmd:`rg -n -i '${pat}' --glob '*.go' --glob '*.proto' --glob '*.yaml' --glob '*.yml' --glob '*.md' . | head -160`,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:7000});
  return `=== ${label} ===\n${r.output}`;
}));
out.forEach(text);

